roles/chaldea_client/templates/route.jso:
{% if chaldea_client_route_targets | length == 0 and chaldea_client_claude_usage_source | length == 0 %}
{
  "paceMargin": {{ chaldea_client_pace_margin | to_json }},
  "minimumRemaining": {{ chaldea_client_minimum_remaining | to_json }},
  "failureMargin": {{ chaldea_client_route_failure_margin | to_json }},
  "minimumTurns": {{ chaldea_client_route_minimum_turns | to_json }},
  "quotaMaxAgeMs": {{ chaldea_client_quota_max_age_ms | to_json }},
  "analyticsMaxAgeMs": {{ chaldea_client_analytics_max_age_ms | to_json }},
  "t3BaseDir": {{ chaldea_client_t3_home | to_json }},
  "tokenFile": {{ chaldea_client_quota_token | to_json }},
  "claudeUsage": {
    "enabled": {{ chaldea_client_claude_usage_enabled | bool | to_json }},
    "providerInstanceId": {{ chaldea_client_claude_usage_provider | to_json }}
  }
}
{% else %}
{% set base = {
  "paceMargin": chaldea_client_pace_margin,
  "minimumRemaining": chaldea_client_minimum_remaining,
  "failureMargin": chaldea_client_route_failure_margin,
  "minimumTurns": chaldea_client_route_minimum_turns,
  "quotaMaxAgeMs": chaldea_client_quota_max_age_ms,
  "analyticsMaxAgeMs": chaldea_client_analytics_max_age_ms,
  "t3BaseDir": chaldea_client_t3_home,
  "tokenFile": chaldea_client_quota_token,
  "claudeUsage": {
    "enabled": chaldea_client_claude_usage_enabled | bool,
    "providerInstanceId": chaldea_client_claude_usage_provider
  } | combine(chaldea_client_claude_usage_source)
} %}
{{ base | combine(chaldea_client_route_targets) | to_nice_json }}
{% endif %}

roles/chaldea_client/templates/quota.jso:
{{ {
  'contexts': [] if chaldea_client_quota_runtime_enabled else [{
    'providers': chaldea_client_codex_providers,
    'home': fleet_home,
    'codexHome': chaldea_client_codex_home,
    'command': chaldea_client_codex_command,
    'assertRuntimeHome': chaldea_client_codex_assert_runtime_home | bool
  }],
  'lowHeadroomPercent': chaldea_client_low_headroom_percent
} | combine({'claudeContexts': chaldea_client_claude_contexts} if not chaldea_client_quota_runtime_enabled and chaldea_client_claude_contexts | length else {}) | combine({'fleet': chaldea_client_quota_fleet} if chaldea_client_quota_fleet | length else {}) | to_nice_json }}

roles/chaldea_token_helper/templates/tok:
{{ {
  'issuer': chaldea_token_helper_issuer,
  'state_file': chaldea_token_helper_state,
  'bundle_file': chaldea_access_paths.bundle,
  'anchor_file': chaldea_access_paths.root ~ '/anchors.json',
  'clock_health_file': chaldea_access_paths.clock_health,
  'grants': chaldea_token_helper_grants
} | to_nice_json }}

roles/chaldea_token_helper/templates/sud:
# Managed by chaldea-fleet-config. Exact selectors only; no shell or Node grant.
Defaults!/usr/local/libexec/chaldea-token-helper-issuer env_reset,secure_path="/usr/bin:/bin"
{% for grant in chaldea_token_helper_grants %}
#{{ grant.uid }} ALL=(chaldea-issuer) NOPASSWD: NOSETENV: /usr/local/libexec/chaldea-token-helper-issuer --audience {{ grant.audience }} --action {{ grant.action }} --source {{ grant.source }} --host {{ grant.host }} --kind {{ grant.kind }}
{% endfor %}
